      hu: ["A szobrot 1958-ban állították fel Tbiliszi 1500 éves évfordulójára.", "A magassága 20 méter.", "A szobrász, Elguja Amashukeli Állami Díjat kapott érte.", "A bal kezében lévő tál a vendégszeretetet szimbolizálja.", "A jobb kezében lévő kard a védelmi készséget jelképezi.", "A jelenlegi alumínium változatot a 90-es években helyezték el."],
      ro: ["Statuia a fost inaugurată în 1958.", "Are o înălțime totală de 20 de metri.", "Materialul principal folosit astăzi este aluminiul.", "A fost creată de sculptorul Elguja Amashukeli.", "Simbolizează ospitalitatea georgiană și spiritul de luptător.", "Este situată în apropierea grădinii botanice și a cetății Narikala."],
      en: ["The statue was erected in 1958 for the city's 1500th anniversary.", "It stands at a height of 20 meters.", "The original wooden model was covered in aluminum in 1963.", "The wine bowl represents the country's hospitality.", "The sword represents the struggle for freedom and defense.", "It was designed by the famous Georgian sculptor Elguja Amashukeli."],
      es: ["La estatua fue erigida en 1958 por el 1500 aniversario de Tiflis.", "Mide exactamente 20 metros de altura.", "El escultor Elguja Amashukeli diseñó el monumento.", "Sostiene una copa de vino en la mano izquierda y una espada en la derecha.", "La estatua está hecha hoy completamente de aluminio.", "Se encuentra en la colina Sololaki, por encima del casco antiguo."],
      pt: ["A estátua foi erguida em 1958 para o 1500.º aniversário de Tiblíssi.", "Tem exatamente 20 metros de altura.", "O escultor Elguja Amashukeli projetou o monumento.", "Na mão esquerda segura uma taça de vinho, na direita uma espada.", "A estátua consiste hoje inteiramente de alumínio.", "Situa-se na colina de Sololaki acima da cidade antiga."],
      fr: ["La statue a été érigée en 1958 pour le 1 500e anniversaire de Tbilissi.", "Elle mesure précisément 20 mètres de haut.", "Le sculpteur Elguja Amashukeli a conçu le monument.", "Elle tient une coupe de vin dans la main gauche et une épée dans la droite.", "La statue est aujourd'hui entièrement faite d'aluminium.", "Elle se trouve sur la colline de Sololaki surplombant la vieille ville."],
